import{editedDNA,triplets}from './gen-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f7f3ed" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const line=(d,c='#bad0ce',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}"/>`;
const dot=(x,y,r=12,c='#e9ac96')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#e9ddc4"/>`;
export const genSVG=(a,label)=>`<svg viewBox="0 0 560 420" role="img" aria-label="${esc(label)}">${a}</svg>`;
export function nucleotideFigure({kind='nucleotide'}={}){let a=tx(280,30,'A nucleotide: phosphate + sugar + base',22);for(let i=0;i<3;i++){let y=105+i*91;a+=dot(145,y,23,'#8caeb9')+tx(145,y+6,'P')+line(`M168 ${y}h60`)+`<path d="M253 ${y-28}l29 21-11 34h-36l-11-34Z" fill="#a8bfa9" stroke="#e6ddc9"/>`+tx(253,y+5,'S')+line(`M282 ${y}h47`)+`<rect x="329" y="${y-22}" width="72" height="44" rx="8" fill="#b68273"/>`+tx(365,y+6,['A','C','G'][i]);if(i<2)a+=line(`M253 ${y+28}L145 ${y+68}`);}a+=tx(90,365,'P: phosphate',14)+tx(265,365,'S: sugar',14)+tx(430,365,'A/C/G/T: base',14)+tx(280,402,'Alternating sugar/phosphate backbone · diagram enlarged',13);return genSVG(a,'Three repeating DNA nucleotides. Phosphate P joins sugar S; each sugar carries a base. Four possible bases are A,C,G,T.');}
export function synthesisFigure({progress=0}={}){let p=Math.max(0,Math.min(1,Number(progress)||0)),n=Math.min(3,Math.floor(p*4)),a=tx(280,30,'Template → amino-acid chain → folded protein',21);a+=`<rect x="75" y="80" width="410" height="50" rx="12" fill="#456276"/>`+tx(280,112,'Template information from a gene',18);a+=`<ellipse cx="280" cy="226" rx="98" ry="53" fill="#9db9ad" stroke="#e7ddc5"/>`+tx(280,232,'Ribosome',19);let count=Math.max(1,Math.min(6,Math.floor(p*7)));for(let i=0;i<count;i++){let x=n<3?110+i*38:280+Math.cos(i*.95)*62,y=n<3?320:315+Math.sin(i*.95)*42;if(i)a+=line(`M${n<3?110+(i-1)*38:280+Math.cos((i-1)*.95)*62} ${n<3?320:315+Math.sin((i-1)*.95)*42}L${x} ${y}`);a+=dot(x,y,13,i%2?'#b4cbd1':'#e9ac96')+tx(x,y+5,String(i+1),13);}if(n===1||n===2){let x=440-(p*4%1)*90;a+=line(`M${x} 155v35h-25`)+dot(x,155,12)+tx(440,210,'Carrier',13);}a+=tx(280,392,['Gene provides the sequence information','Carriers deliver specific amino acids','Amino acids join in specified order','Completed chain folds; shape affects function'][n],16);return genSVG(a,'Simplified protein synthesis stage '+(n+1)+'. Template-derived information guides a ribosome; carrier molecules deliver amino acids. Completed chain folds. Not detailed RNA structures.');}
export function variantFigure({state='',kind='variants',progress=.5}={}){let a=tx(280,30,kind==='expression'?'Non-coding regions can regulate expression':'Compare genetic changes and possible effects',22);if(kind==='edit'){let mode=state||'insert',s=editedDNA(mode);a+=tx(280,115,'Original: AAA · CCC · GGG',21)+tx(280,200,(mode==='delete'?'Deletion: ':'Insertion: ')+triplets(s).join(' · '),21)+tx(280,290,'Changed grouping may alter following information',17)+tx(280,380,'Token model, not a real amino-acid lookup table',14);}else if(kind==='expression'){let off=state==='off';a+=`<rect x="65" y="125" width="150" height="70" rx="18" fill="#826c68"/>`+tx(140,166,'Switch region',18)+line('M218 160h70')+`<rect x="290" y="125" width="190" height="70" rx="18" fill="#4c6a7c"/>`+tx(385,166,'Coding region',18);for(let i=0;i<(off?2:5);i++)a+=dot(155+i*55,285,15);a+=tx(280,370,'Expression amount can change without changing sequence',16);}else{let n=Math.min(3,Math.floor(Math.max(0,Math.min(1,progress))*4));a+=tx(280,110,['DNA variant occurs','Some changes leave function unchanged','Some changes alter shape/activity','Non-coding changes may alter expression'][n],19);for(let i=0;i<6;i++)a+=dot(150+i*50,205+(n===2?Math.sin(i)*25:0),13,i===3&&n===2?'#b4d0d1':'#e9ac96');a+=tx(280,300,'Most mutations have no effect or only small effects',18)+tx(280,380,'Possible pathways, not inevitable disease or benefit',15);}return genSVG(a,'Variant model: '+kind+'. '+state+'. Effects depend on the variant; not all mutations change protein function.');}
export function crossFigure({rows=['A','a'],cols=['A','a'],cells=['','','','']}={}){let a=tx(280,30,'Combine one supplied gamete from each parent',21);for(let j=0;j<2;j++){a+=tx(235+j*125,103,cols[j],24)+tx(115,188+j*105,rows[j],24);for(let k=0;k<2;k++){let x=170+k*125,y=130+j*105;a+=`<rect x="${x}" y="${y}" width="120" height="100" rx="14" fill="#38566c" stroke="#aecac6"/>`+tx(x+60,y+58,cells[j*2+k]||'?',25);}}a+=tx(280,385,'Possible combinations · not a scheduled sequence of births',15);return genSVG(a,'Punnett square. Column gametes '+cols.join(',')+'; row gametes '+rows.join(',')+'. Student cells '+cells.map(v=>v||'blank').join(',')+'.');}
export function alleleFigure({state='Aa'}={}){let s=['AA','Aa','aa'].includes(state)?state:'Aa';return genSVG(tx(280,35,'Genotype and phenotype: a bounded model',22)+dot(235,175,42,'#b4cbd1')+dot(325,175,42,'#e7ac98')+tx(235,185,s[0],30)+tx(325,185,s[1],30)+tx(280,270,s==='Aa'?'Different alleles: heterozygous':'Same alleles: homozygous',21)+tx(280,330,s==='aa'?'Recessive phenotype':'A dominant: dominant phenotype',20)+tx(280,395,'Most characteristics involve multiple genes',15),'Simple paired-gene model: '+s+'. Dominance describes expression, not frequency or value.');}
export function genFigure(o={}){if(o.concealed)return genSVG(tx(280,210,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(['nucleotide','backbone'].includes(o.kind))return nucleotideFigure(o);if(o.kind==='synthesis')return synthesisFigure(o);if(['variants','edit','expression'].includes(o.kind))return variantFigure(o);if(o.kind==='cross')return crossFigure(o);if(o.kind==='alleles')return alleleFigure(o);let rows=o.kind==='pairing'?['A ↔ T','C ↔ G','Complementary opposite strands']:o.kind==='triplet'?['Invented code: AAA → token1; CCC → token2','AAA CCC and CCC AAA give different orders','Base order → amino-acid order']:o.kind==='function'?['Protein sequence → folding → shape','Enzymes, hormones and structural proteins','Shape contributes to function']:['Simple single-gene models have limits','Most traits involve multiple genes','Probability per event is not a guaranteed family ratio'];return genSVG(tx(280,35,'Read the model and its limits',23)+rows.map((s,i)=>tx(280,130+i*90,s,17)).join(''),'Teaching comparison. '+rows.join('. '));}
